def solve(n):
    C = 2 * n + 1
    positions = []

    # P_i = (i*(i+1)/2 - 1) mod C for i >= 1
    for i in range(1, C + 1):
        # Calculate triangular number T_i = i*(i+1)/2
        T_i = i * (i + 1) // 2
        P_i = (T_i - 1) % C
        positions.append(P_i)

    counts = {}
    for p in positions:
        counts[p] = counts.get(p, 0) + 1

    heads_down_count = 0
    for p, count in counts.items():
        if count % 2 != 0:
            heads_down_count += 1

    return heads_down_count

# Test for small n
test_n_values = range(1, 11)
results = {}
for n in test_n_values:
    results[n] = solve(n)

print(f"Results for n=1 to n=10: {results}")

# Test for a large n to increase confidence
n_large = 100
print(f"Result for n={n_large}: {solve(n_large)}")
